xpath.script:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much can AI Marketing Copilot improve my ROI?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Based on real deployments, users report 35% average ROI improvement within 3 months. One marketing agency managing 50+ accounts reduced marketing spend by 18% while maintaining revenue."
      }
    },
    {
      "@type": "Question",
      "name": "What data sources does AI Marketing Copilot need?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The module analyzes Odoo CRM, sales, and accounting data. Optional: integrations with Google Ads API, Meta Ads API, email marketing platforms, HubSpot. Works fine with Odoo data alone."
      }
    },
    {
      "@type": "Question",
      "name": "Can AI Marketing Copilot work with my existing marketing tools?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. AI Marketing Copilot provides JSON API and webhooks. You can send recommendations to HubSpot, Klaviyo, or any email platform. Bidirectional sync available for campaign metrics."
      }
    },
    {
      "@type": "Question",
      "name": "Is the code open source or proprietary?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Published on Odoo Apps Store as a full module. Source code follows LGPL-3 license (standard for Odoo addons). Full transparency, no hidden algorithms."
      }
    },
    {
      "@type": "Question",
      "name": "Does it support Arabic/RTL interfaces?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, fully bilingual (Arabic + English) with RTL support. All labels, reports, and dashboards are translated. Customizable for any language."
      }
    },
    {
      "@type": "Question",
      "name": "What is the learning curve?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Zero setup required. Install from Odoo Apps Store, enable demo data, and recommendations appear immediately. No machine learning training needed. Customizable via UI without coding."
      }
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How much will AI POS Copilot increase my sales?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Real deployments show 24% average basket size increase. Retail chains report 42% suggestion acceptance rate. For a store with 200 daily transactions at 100 EGP avg., that's 3,360,000 EGP extra monthly revenue (+24%)."
      }
    },
    {
      "@type": "Question",
      "name": "Will my cashiers resist the AI suggestions?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The suggestion appears as a sidebar widget that doesn't interrupt checkout. Cashiers click 'add' in 1 tap or ignore it. No training required. Usage is 85%+."
      }
    },
    {
      "@type": "Question",
      "name": "Can I customize which products are suggested?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Tag products as complementary (shoes + socks, coffee + pastry). The system learns from your tagging and user behavior. Rule engine available for advanced setups."
      }
    },
    {
      "@type": "Question",
      "name": "Does it work with slow-moving inventory?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. AI POS Copilot can suggest overstocked items to clear them. Useful for seasonal stock, end-of-life products, clearance sales."
      }
    },
    {
      "@type": "Question",
      "name": "What languages are supported?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fully bilingual: Arabic (RTL) and English. Interface, product names, and prompts adapt automatically. Easy to add more languages."
      }
    },
    {
      "@type": "Question",
      "name": "How does it handle new products?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "New products are suggested based on category tags and similarity to existing products. No manual tagging required, but tagging improves accuracy."
      }
    }
  ]
}
